using TaiChuWeb_V2.Models.Project;
using TaiChuWeb_V2.Models.LingMai;
using TaiChuWeb_V2.Models.User;
using TaiChuWeb_V2.Services.Project;

static class CommunityChecks
{
    public static async Task<int> Run()
    {
        int checks = 0; void Check(bool value, string label) { checks++; if (!value) throw new Exception(label); }
        var user = Guid.NewGuid();
        ControllerContext Login() => new() { HttpContext = new DefaultHttpContext { User = new ClaimsPrincipal(new ClaimsIdentity(new[] { new Claim(ClaimTypes.NameIdentifier, user.ToString()) }, "test")) } };
        var db = new TestContext(); db.UserRows.Rows.Add(new() { Id = user, Username = "贡献者" });
        db.WikiCategoryRows.Rows.Add(new() { Id = 1, Name = "资料" });
        db.WikiRows.Rows.Add(new() { Id = "wiki", Title = "资料", CurrentRevisionId = 2, CategoryId = 1 });
        const string content = "{\"type\":\"doc\",\"content\":[]}";
        db.RevisionRows.Rows.AddRange(new[] {
            new WikiArticleRevision { Id = 1, ArticleId = "wiki", Content = content, Status = 1, ContributorId = user.ToString() },
            new WikiArticleRevision { Id = 2, ArticleId = "wiki", Content = content, Status = 1, PreviousRevisionId = 1, ContributorId = user.ToString() },
            new WikiArticleRevision { Id = 3, ArticleId = "wiki", Content = "private pending", Status = 0, PreviousRevisionId = 2, ContributorId = user.ToString() },
            new WikiArticleRevision { Id = 4, ArticleId = "another", Content = "other article", Status = 1 }
        });
        var wiki = new WikiController(db) { ControllerContext = Login() };
        var history = JsonSerializer.Serialize(((OkObjectResult)await wiki.History("wiki")).Value);
        Check(history.Contains("贡献者", StringComparison.Ordinal) || history.Contains("\\u8D21"), "history resolves contributor names");
        Check(!history.Contains("private pending") && !history.Contains("other article"), "public history excludes pending/other articles");
        Check(await wiki.Revision("wiki", 3) is NotFoundResult, "pending revision is not public");
        Check(await wiki.Revision("wiki", 4) is NotFoundResult, "revision must belong to article");
        var diff = JsonSerializer.Serialize(((OkObjectResult)await wiki.Revision("wiki", 2)).Value);
        Check(diff.Contains("previousContent"), "comparison includes original snapshot");
        var stale = await wiki.UpdateFromNote(new WikiUpdateDto { ArticleId = "wiki", BaseRevisionId = 1, Content = content });
        Check(stale is ConflictObjectResult && db.Saves == 0, "stale edit does not insert revision");
        var update = await wiki.UpdateFromNote(new WikiUpdateDto { ArticleId = "wiki", BaseRevisionId = 2, Content = content, Summary = "修正段落" });
        Check(update is OkObjectResult && db.RevisionRows.Rows.Last().PreviousRevisionId == 2 && db.RevisionRows.Rows.Last().Status == 0, "editing records base and waits for review");
        var review = new WikiReviewController(db) { ControllerContext = Login() };
        Check(await review.HandleRevision(3, new ReviewRequestDto { Approved = true }) is ForbidResult, "ordinary user cannot approve");
        Check(await review.CleanupDeletedArticles() is ForbidResult, "ordinary user cannot clean history");
        Check(await review.ToggleArchive("wiki") is ForbidResult, "ordinary user cannot archive");
        db.PermissionRows.Rows.Add(new() { UserId = user, Permission = AdminPermission.Wiki_Editor });
        Check(await review.Rollback("wiki", 4) is NotFoundResult, "cannot roll another article into this one");
        Check(await review.HandleRevision(3, new ReviewRequestDto { Approved = true }) is OkObjectResult, "moderator can approve current proposal");
        Check(db.WikiRows.Rows[0].CurrentRevisionId == 3, "approval advances current version");
        Check(await review.HandleRevision(3, new ReviewRequestDto { Approved = true }) is ConflictObjectResult, "cannot approve twice");
        Check(await review.HandleRevision(db.RevisionRows.Rows.Last().Id, new ReviewRequestDto { Approved = true }) is ConflictObjectResult, "another proposal on the previous base conflicts");
        db.WikiRows.Rows[0].IsDeleted = true;
        Check(await wiki.GetArticleDetail("wiki") is NotFoundResult && await wiki.History("wiki") is NotFoundResult, "archived wiki unavailable through detail/history");

        var visible = new TestContext();
        var source = Guid.NewGuid(); visible.NoteRows.Rows.Add(new Note { Id = source, IsPublic = false });
        visible.PublishedRows.Rows.Add(new PublishedNote { Id = Guid.NewGuid(), OriginalNoteId = source, Type = "blog", Title = "private" });
        visible.PublishedRows.Rows.Add(new PublishedNote { Id = Guid.NewGuid(), Type = "blog", Title = "legacy public" });
        visible.WikiRows.Rows.Add(new WikiArticle { Id = "hidden", CurrentRevisionId = 1, IsDeleted = true });
        visible.WikiRows.Rows.Add(new WikiArticle { Id = "pending" });
        Check(CatalogController.Query(visible, "all").Count() == 1, "catalog hides private sources, archived and pending wiki");
        visible.NoteRows.Rows[0].IsPublic = true; Check(CatalogController.Query(visible, "all").Count() == 2, "published source enters catalog");
        visible.NoteRows.Rows[0].Status = 2; Check(CatalogController.Query(visible, "all").Count() == 1, "removed source leaves catalog");
        visible.PublishedRows.Rows[1].Excerpt = JsonSerializer.Serialize(new { text = "风景练习", coverUrl = "https://example.invalid/cover.png" });
        var catalog = new CatalogController(visible);
        var found = JsonSerializer.Serialize(((OkObjectResult)await catalog.Get("blog", "风景")).Value);
        Check(found.Contains("\"total\":1") && found.Contains("cover.png"), "catalog searches escaped legacy summary and restores cover");
        visible.WikiCategoryRows.Rows.Add(new() { Id = 2, ParentId = 1, Name = "子分类" });
        visible.WikiRows.Rows.Add(new() { Id = "child", Title = "子分类词条", CategoryId = 2, CurrentRevisionId = 1 });
        var children = JsonSerializer.Serialize(((OkObjectResult)await catalog.Get("wiki", categoryId: 1)).Value);
        Check(children.Contains("\"total\":1") && children.Contains("child"), "parent category includes existing child articles");

        var projects = new TestContext();
        projects.ProjectRows.Rows.Add(new Project { Id = "p", OwnerId = Guid.NewGuid(), Name = "项目" });
        projects.MemberRows.Rows.Add(new ProjectMember { ProjectId = "p", UserId = user.ToString(), RoleIds = new() { "foreign", "system" } });
        projects.RoleRows.Rows.Add(new ProjectCustomRole { Id = "foreign", ProjectId = "q", Name = "外部角色", PermissionsJson = "[\"task:manage\"]" });
        projects.RoleRows.Rows.Add(new ProjectCustomRole { Id = "system", ProjectId = null, IsSystemDefault = true, Name = "系统模板", PermissionsJson = "[\"task:move_self\"]" });
        var permission = new ProjectPermissionService(projects);
        Check(!await permission.HasPermissionAsync("p", user.ToString(), "task:manage"), "foreign project role cannot grant access");
        Check(await permission.HasPermissionAsync("p", user.ToString(), "task:move_self"), "system role templates remain supported");
        projects.RoleRows.Rows[1].PermissionsJson = "{";
        Check((await permission.GetUserPermissionsAsync("p", user.ToString())).Count == 0, "malformed role does not crash permissions");
        projects.ProjectRows.Rows[0].OwnerId = user;
        projects.CategoryRows.Rows.Add(new ProjectCategory { Id = "foreign-category", ProjectId = "q", Name = "其他项目" });
        var kanban = new ProjectKanbanController(projects, permission) { ControllerContext = Login() };
        Check(await kanban.CreateTask("p", new CreateTaskDto { Title = "测试", CategoryId = "foreign-category" }) is BadRequestObjectResult, "cannot create task in foreign project category");
        Check(projects.TaskRows.Rows.Count == 0, "invalid category does not write task");
        var delivery = new TaiChuWeb_V2.Controllers.Project.ProjectDeliveryController(projects, permission) { ControllerContext = Login() };
        var outsider = Guid.NewGuid();
        projects.UserRows.Rows.Add(new User { Id = outsider, Username = "外部协作者" });
        var dto = new TaiChuWeb_V2.Controllers.Project.DeliveryDto { MemberId = outsider, TaskName = "交付", RecordedName = "伪造名字", TimingStatus = "按时", QualityStatus = "达标", CommStatus = "正常" };
        Check(await delivery.CreateDelivery("p", dto) is OkObjectResult, "manager can record external contributor");
        Check(projects.DeliveryRows.Rows.Single().RecordedName == "外部协作者", "delivery records actual user name");
        projects.DeliveryRows.Rows[0].AdminNote = "manager-only-note";
        Check(JsonSerializer.Serialize(((OkObjectResult)await delivery.GetDeliveries("p")).Value).Contains("manager-only-note"), "manager sees internal delivery note");
        projects.ProjectRows.Rows[0].OwnerId = Guid.NewGuid();
        Check(!JsonSerializer.Serialize(((OkObjectResult)await delivery.GetDeliveries("p")).Value).Contains("manager-only-note"), "ordinary member cannot read management note");
        Check(await delivery.CreateDelivery("p", dto) is ForbidResult, "ordinary member cannot create delivery");
        Check(await delivery.DeleteDelivery("p", projects.DeliveryRows.Rows[0].Id) is ForbidResult, "ordinary member cannot delete delivery");
        projects.MemberRows.Rows.Clear();
        Check(await delivery.GetDeliveries("p") is ForbidResult, "outside user cannot read internal delivery records");
        var topics = new TestContext();
        topics.PublishedRows.Rows.AddRange(new[] {
            new PublishedNote { Id = Guid.NewGuid(), Type = "post", Title = "literal", Tags = "[\"我的世界\"]", PublishedAt = DateTime.UtcNow.AddMinutes(-1) },
            new PublishedNote { Id = Guid.NewGuid(), Type = "post", Title = "escaped", Tags = JsonSerializer.Serialize(new[] { "我的世界" }), PublishedAt = DateTime.UtcNow.AddMinutes(-2) },
            new PublishedNote { Id = Guid.NewGuid(), Type = "post", Title = "different", Tags = "[\"我的世界观\"]", PublishedAt = DateTime.UtcNow },
            new PublishedNote { Id = Guid.NewGuid(), Type = "blog", Title = "blog", Tags = "我的世界" }
        });
        var stream = new TaiChuWeb_V2.Controllers.LingMai.LingMaiPublishController(topics, Array.Empty<TaiChuWeb_V2.Services.Publish.ILingMaiPublishHandler>());
        JsonElement Rows(IActionResult result) => JsonSerializer.SerializeToElement(((OkObjectResult)result).Value);
        var tagged = Rows(await stream.GetPublicStream("post", tag: " 我的世界 "));
        Check(tagged.GetArrayLength() == 2, "topic matches escaped and literal JSON but not longer tags");
        var secondPage = Rows(await stream.GetPublicStream("post", page: 2, pageSize: 1, tag: "我的世界"));
        Check(secondPage[0].GetProperty("Title").GetString() == "escaped", "topic filter applies before pagination");
        Check(Rows(await stream.GetPublicStream(null, tag: "我的世界")).GetArrayLength() == 3, "topic includes existing blogs and legacy single tags");
        Check(Rows(await stream.GetPublicStream(null, page: 1)).GetArrayLength() == 4, "omitting topic retains original stream");
        Check(await stream.GetPublicStream(null, tag: new string('a', 51)) is BadRequestObjectResult, "overlong topic is rejected");
        var privateSource = Guid.NewGuid();
        topics.NoteRows.Rows.Add(new Note { Id = privateSource, IsPublic = false });
        topics.PublishedRows.Rows[0].OriginalNoteId = privateSource;
        Check(Rows(await stream.GetPublicStream("post", tag: "我的世界")).GetArrayLength() == 1, "topic cannot expose withdrawn content");
        return checks;
    }
}

using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using TaiChuWeb_V2.Controllers.ChaiCommunity;
using TaiChuWeb_V2.Dtos.Chai.Battle;
using TaiChuWeb_V2.Dtos.Chai.Joint;
using TaiChuWeb_V2.Models.ChaiCommunity;
using TaiChuWeb_V2.Models.ChaiCommunity.Battle;
using TaiChuWeb_V2.Models.ChaiCommunity.Joint;
using TaiChuWeb_V2.Controllers.Club;
using TaiChuWeb_V2.Models.Club;

static class JointBattleChecks
{
    public static async Task<int> Run()
    {
        int checks = 0;
        void Check(bool value, string label) { checks++; if (!value) throw new Exception(label); }
        var owner = Guid.NewGuid(); var guest = Guid.NewGuid(); var teammate = Guid.NewGuid();
        ControllerContext Login(Guid user) => new() { HttpContext = new DefaultHttpContext {
            User = new ClaimsPrincipal(new ClaimsIdentity(new[] { new Claim(ClaimTypes.NameIdentifier, user.ToString()), new Claim(ClaimTypes.Name, "测试") }, "test")) } };
        var db = new TestContext();
        var joints = new TestSet<JointActivity>(); db.JointActivities = joints;
        var activity = new JointActivity { Id = Guid.NewGuid(), OrganizerId = owner, Title = "联创", Description = "说明", StartDate = DateTime.UtcNow.AddDays(1), EndDate = DateTime.UtcNow.AddDays(2), OrganizerType = "user", Status = "open" };
        joints.Rows.Add(activity);
        var joint = new JointController(db) { ControllerContext = Login(owner) };
        var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);
        var omitted = JsonSerializer.Deserialize<UpdateJointRequest>("{\"contact\":\"\"}", jsonOptions)!;
        Check(!omitted.EndDateSpecified, "omitted end date remains unspecified");
        Check((await joint.Update(activity.Id, omitted)).Result is OkObjectResult && activity.EndDate != null, "partial edit preserves end date");
        var clear = JsonSerializer.Deserialize<UpdateJointRequest>("{\"endDate\":null}", jsonOptions)!;
        Check(clear.EndDateSpecified, "explicit null is tracked");
        Check((await joint.Update(activity.Id, clear)).Result is OkObjectResult && activity.EndDate == null, "edit clears optional end date");
        Check((await joint.Update(activity.Id, new() { Title = "不应保存", EndDate = activity.StartDate })).Result is BadRequestObjectResult && activity.Title == "联创", "invalid dates leave fields unchanged");
        joint.ControllerContext = Login(guest);
        Check((await joint.Update(activity.Id, new() { Title = "越权" })).Result is ForbidResult, "non-owner cannot edit");

        var battles = new TestSet<Battle>(); db.Battles = battles;
        var ocs = new TestSet<StickmanCharacter>(); db.StickmanCharacters = ocs;
        StickmanCharacter Oc(Guid author) { var oc = new StickmanCharacter { Id = Guid.NewGuid(), AuthorId = author, Title = "测试OC", Status = "published", IsBattleEnabled = true }; ocs.Rows.Add(oc); return oc; }
        var ownOc = Oc(owner); var guestOc = Oc(guest); var mateOc = Oc(teammate);
        var controller = new BattleController(db) { ControllerContext = Login(owner) };
        CreateBattleRequest Request() => new() { Title = "流程验收", BattleType = "2v1", Rules = "测试", JudgmentType = "internal", ChallengerOcIds = new() { ownOc.Id }, OpponentOcIds = new() { [guest] = new() { guestOc.Id }, [teammate] = new() { mateOc.Id } }, BattleConfigJson = JsonSerializer.Serialize(new { teams = new Dictionary<Guid, int> { [owner] = 1, [guest] = 2, [teammate] = 1 }, custom = "preserved" }) };
        mateOc.Status = "draft";
        Check((await controller.Create(Request())).Result is BadRequestObjectResult && battles.Rows.Count == 0, "validate second invited user's OC");
        mateOc.Status = "published";
        var created = await controller.Create(Request());
        Check(created.Result is OkObjectResult, "create multi-user invitation");
        var battle = battles.Rows.Single();
        Check(battle.Participants.Count == 1 && battle.Participants.Single().TeamNumber == 1, "invitation is not automatic participation");
        Check(battle.BattleConfigJson.Contains("preserved"), "custom configuration survives");
        Check((await controller.Unregister(battle.Id)).Result is BadRequestObjectResult && battle.Participants.Count == 1, "initiator cannot unregister and transfer ownership");
        controller.ControllerContext = Login(guest);
        Check((await controller.Reject(battle.Id)).Result is OkObjectResult, "guest rejects own invitation");
        Check(!battle.IsPublic && JsonSerializer.Deserialize<Dictionary<Guid, List<Guid>>>(battle.OpponentOcIds!)!.ContainsKey(teammate), "other invitation survives rejection");
        Check((await controller.Register(battle.Id, new() { OcIds = new() { guestOc.Id } })).Result is BadRequestObjectResult, "removed invitation cannot register while private");
        controller.ControllerContext = Login(teammate);
        var conflict = new Battle { Id = "other", Participants = new List<BattleParticipant> { new() { UserId = teammate, OcIdsJson = JsonSerializer.Serialize(new[] { mateOc.Id }) } } };
        battles.Rows.Add(conflict);
        Check((await controller.Register(battle.Id, new() { OcIds = new() { mateOc.Id } })).Result is BadRequestObjectResult, "registration rejects OC active elsewhere");
        battles.Rows.Remove(conflict);
        Check((await controller.Register(battle.Id, new() { OcIds = new() { mateOc.Id } })).Result is OkObjectResult, "invited teammate accepts");
        Check(battle.Participants.Single(p => p.UserId == teammate).TeamNumber == 1, "teammate remains on team A");
        Check((await controller.Reject(battle.Id)).Result is BadRequestObjectResult, "participant cannot reject accepted invitation");
        Check((await controller.CloseRegistration(battle.Id)).Result is ForbidResult, "participant cannot advance organizer workflow");
        controller.ControllerContext = Login(owner);
        Check((await controller.CloseRegistration(battle.Id)).Result is OkObjectResult && battle.Status == "ongoing", "owner starts creation after two participants");
        Check((await controller.SubmitWork(battle.Id, new() { Title = "作品", ContentUrl = "https://example.invalid/work" })).Result is OkObjectResult, "participant submits work");
        Check((await controller.SubmitWork(battle.Id, new() { Title = "重复", ContentUrl = "https://example.invalid/work" })).Result is BadRequestObjectResult, "duplicate submission rejected");
        Check((await controller.CloseCreation(battle.Id)).Result is OkObjectResult && battle.Status == "judging", "owner advances to judging");
        Check((await controller.SetInternalResult(battle.Id, new() { WinnerIds = new() { battle.Participants.First().Id } })).Result is OkObjectResult, "owner records internal result");
        Check((await controller.PublishResult(battle.Id)).Result is OkObjectResult && battle.Status == "finished", "owner publishes recorded result");
        // 只验证派单权限与前置状态；不进入计价、结算或退款分支。
        var club = new TestContext();
        var services = new TestSet<CustomerService>(); club.CustomerServices = services;
        var orders = new TestSet<ClubOrder>(); club.ClubOrders = orders;
        var cs = new CsController(club) { ControllerContext = Login(owner) };
        Check(await cs.AssignOperator("test", new()) is BadRequestObjectResult, "non-CS account cannot assign");
        Check(await cs.ReassignOperators("test", new()) is BadRequestObjectResult, "non-CS account cannot reassign");
        var service = new CustomerService { UserId = owner, AuditStatus = "approved" }; services.Rows.Add(service);
        var order = new ClubOrder { OrderNo = "test", CustomerServiceId = Guid.NewGuid(), Status = "pending" }; orders.Rows.Add(order);
        Check(await cs.AssignOperator("test", new()) is ObjectResult { StatusCode: 403 }, "CS cannot assign another service's order");
        order.CustomerServiceId = service.Id;
        Check(await cs.AssignOperator("test", new()) is BadRequestObjectResult, "unconfirmed payment blocks assignment");
        Check(await cs.ReassignOperators("test", new() { Reason = "测试" }) is BadRequestObjectResult, "pending order cannot reassign");
        Check(club.Saves == 0, "CS permission checks never write or settle orders");
        var projectDb = new TestContext();
        var documents = new TestSet<TaiChuWeb_V2.Models.Project.ProjectDocument>(); projectDb.ProjectDocuments = documents;
        var project = new TaiChuWeb_V2.Models.Project.Project { Id = "shared", OwnerId = owner, Name = "协作" };
        projectDb.ProjectRows.Rows.Add(project);
        projectDb.MemberRows.Rows.Add(new() { ProjectId = project.Id, UserId = owner.ToString() });
        projectDb.MemberRows.Rows.Add(new() { ProjectId = project.Id, UserId = guest.ToString() });
        var note = new TaiChuWeb_V2.Models.LingMai.Note { Id = Guid.NewGuid(), AuthorId = owner.ToString(), Type = "doc", Title = "内部文档" };
        projectDb.NoteRows.Rows.Add(note);
        projectDb.BlockRows.Rows.Add(new() { Id = "p", OwnerId = note.Id.ToString(), OwnerType = "doc", Type = "paragraph", Data = "{}" });
        var publisher = new TaiChuWeb_V2.Services.Publish.DocPublishHandler(projectDb);
        Check(await publisher.ExecutePublishAsync(note.Id, teammate.ToString(), null, project.Id) is ForbidResult && projectDb.Saves == 0, "non-member cannot share into project");
        Check(await publisher.ExecutePublishAsync(note.Id, owner.ToString(), null, project.Id) is OkObjectResult && !note.IsPublic, "project sharing keeps private note private");
        await publisher.ExecutePublishAsync(note.Id, owner.ToString(), null, project.Id);
        Check(documents.Rows.Count == 1, "sharing twice creates one link");
        note.IsPublic = true;
        await publisher.ExecutePublishAsync(note.Id, owner.ToString(), null, project.Id);
        Check(note.IsPublic, "sharing preserves an already-public note");
        var reader = new TaiChuWeb_V2.Controllers.Projects.ProjectController(projectDb) { ControllerContext = Login(guest) };
        var detail = await reader.GetProjectDocument(project.Id, note.Id);
        Check(detail is OkObjectResult && JsonSerializer.Serialize(((OkObjectResult)detail).Value).Contains("paragraph"), "project member reads another author's shared blocks");
        Check(await reader.GetProjectDocument(project.Id, Guid.NewGuid()) is NotFoundObjectResult, "project endpoint cannot read unshared notes");
        note.Status = 2;
        Check(await reader.GetProjectDocument(project.Id, note.Id) is NotFoundObjectResult, "removed note cannot be read");
        note.Status = 0;
        projectDb.MemberRows.Rows.RemoveAll(m => m.UserId == guest.ToString());
        Check(await reader.GetProjectDocument(project.Id, note.Id) is ForbidResult, "revoked membership loses shared reading access");
        projectDb.SpaceRows.Rows.Add(new() { Id = note.SpaceId, UserId = owner.ToString() });
        var publication = new TaiChuWeb_V2.Controllers.LingMai.LingMaiPublishController(projectDb, new[] { publisher }) { ControllerContext = Login(guest) };
        Check(await publication.UnpublishNote(note.Id) is ForbidResult && documents.Rows.Count == 1, "reader cannot withdraw author's shared document");
        publication.ControllerContext = Login(owner);
        Check(await publication.UnpublishNote(note.Id) is OkObjectResult && documents.Rows.Count == 0 && note.IsPublic, "unshare removes project links without changing public status");
        reader.ControllerContext = Login(owner);
        Check(await reader.GetProjectDocument(project.Id, note.Id) is NotFoundObjectResult, "withdrawn document is no longer readable from project");
        return checks;
    }
}

using System.Reflection;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Routing;
using TaiChuWeb_V2.Controllers.LingMai;
using TaiChuWeb_V2.Models.LingMai;
using TaiChuWeb_V2.Services.LingMai;
using TaiChuWeb_V2.Services.Publish;

static class PublishGraphChecks
{
    public static async Task<int> Run(SortedDictionary<string, object?> trace)
    {
        int checks = 0;
        void Check(bool ok, string name) { checks++; if (!ok) throw new Exception(name); }
        var user = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var noteId = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var spaceId = Guid.Parse("33333333-3333-3333-3333-333333333333");
        var otherId = Guid.Parse("44444444-4444-4444-4444-444444444444");
        var pubId = Guid.Parse("55555555-5555-5555-5555-555555555555");
        var date = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        ControllerContext Login(bool login) => new() { HttpContext = new DefaultHttpContext { User = new ClaimsPrincipal(new ClaimsIdentity(login ? new[] { new Claim(ClaimTypes.NameIdentifier, user.ToString()) } : Array.Empty<Claim>(), "test")) } };
        object Response(IActionResult r) => r switch
        {
            ObjectResult o => new { status = o.StatusCode ?? 200, body = o.Value },
            StatusCodeResult s => new { status = s.StatusCode, body = (object?)null },
            ForbidResult => new { status = 403, body = (object?)null },
            _ => throw new Exception(r.GetType().Name)
        };
        TestContext Create(string type)
        {
            var db = new TestContext();
            db.NoteRows.Rows.Add(new Note { Id = noteId, SpaceId = spaceId, Type = type, Title = "默认标题", Tags = "tag", ExtraData = "{}", UpdatedAt = date });
            db.SpaceRows.Rows.Add(new Space { Id = spaceId, UserId = user.ToString(), Name = "space" });
            db.UserRows.Rows.Add(new() { Id = user, Username = "author" });
            return db;
        }
        foreach (var type in new[] { "blog", "post" })
        foreach (var scenario in new[] { "new", "update", "empty", "malformed", "long", "missing", "failure", "anonymous" })
        {
            var db = Create(type);
            if (scenario == "missing") db.NoteRows.Rows.Clear();
            if (scenario == "anonymous") db.UserRows.Rows.Clear();
            if (scenario == "failure") db.SaveFailure = new InvalidOperationException("write failed");
            if (scenario == "update") db.PublishedRows.Rows.Add(new PublishedNote { Id = pubId, OriginalNoteId = noteId, SpaceId = spaceId, Type = type, AuthorName = "original", Resonance = 8 });
            db.PublishedBlockRows.Rows.Add(new PublishedBlock { Id = otherId, OwnerId = pubId.ToString(), OwnerType = "note", Data = "old" });
            if (scenario != "empty")
            {
                db.BlockRows.Rows.Add(new Block { Id = otherId.ToString(), OwnerId = noteId.ToString(), OwnerType = type, SortOrder = 2, Type = "paragraph", Data = scenario == "malformed" ? "{" : JsonSerializer.Serialize(new { content = new[] { new { text = scenario == "long" ? new string('x', 350) : "正文" } } }) });
                db.BlockRows.Rows.Add(new Block { Id = "non-guid", OwnerId = noteId.ToString(), OwnerType = type, SortOrder = 3, Type = "container", Data = """{"content":[{"type":"image","attrs":{"src":"cover.png"}}]}""" });
                db.BlockRows.Rows.Add(new Block { Id = "cover", OwnerId = noteId.ToString(), OwnerType = "note", SortOrder = 0, Type = "blog_fixed_cover", Data = """{"url":"blog.png"}""" });
