import { computed, onScopeDispose, ref, watch, type Ref } from 'vue'
import { useUserStore } from '@/stores/user'
import type { CardForm } from './useCardForm'

type Draft = { version: 1; key: string; updatedAt: number; baseline: string; form: CardForm }
type Candidate = Draft & { storageKey: string; raw: string }

// 每个编辑器独占一个存储槽；恢复其他页面的副本也不会接管其写入位置。
export function useCardDraft(form: Ref<CardForm>) {
  const user = useUserStore()
  const writer = crypto.randomUUID()
  const pending = ref<Candidate | null>(null)
  const candidates = ref<Candidate[]>([])
  const savedAt = ref(0), error = ref(''), baseSnapshot = ref('')
  let binding: { key: string; baseKey: string; token: string; userId: string; baseline: string } | undefined
  let restoredFrom: Candidate | undefined
  let paused = false
  let releaseLease: (() => void) | undefined
  const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined
  const active = () => binding && binding.token === user.token && binding.userId === user.userId
  const serverChanged = computed(() => Boolean(pending.value && pending.value.baseline !== binding?.baseline))

  function suspend() {
    releaseLease?.(); releaseLease = undefined
    binding = undefined; restoredFrom = undefined
    pending.value = null; candidates.value = []; savedAt.value = 0; error.value = ''; baseSnapshot.value = ''
  }
  watch(() => [user.token, user.userId], suspend, { flush: 'sync' })
  onScopeDispose(suspend)

  function readCandidate(storageKey: string, baseKey: string): Candidate | null {
    const raw = localStorage.getItem(storageKey)
    if (!raw) return null
    const draft = JSON.parse(raw) as Draft
      // 严格检查表单字段和集合，损坏或不同版本的数据不能进入编辑器。
      const candidate = draft.form
      const strings = ['title', 'type', 'coverImage', 'description'] as const
      const lists = ['galleryImages', 'attributes', 'tags', 'relations', 'contentBlocks', 'timelineEvents'] as const
      if (draft.version !== 1 || draft.key !== baseKey || !Number.isFinite(draft.updatedAt) || typeof draft.baseline !== 'string'
        || !candidate || strings.some(field => typeof candidate[field] !== 'string')
        || lists.some(field => !Array.isArray(candidate[field])) || !candidate.content || typeof candidate.content !== 'object' || Array.isArray(candidate.content)
        || [...candidate.galleryImages, ...candidate.tags].some(value => typeof value !== 'string')
        || candidate.attributes.some(value => !value || typeof value.key !== 'string' || typeof value.type !== 'string')
        || candidate.relations.some(value => !value || typeof value.targetCardId !== 'string' || typeof value.relationType !== 'string')
        || candidate.contentBlocks.some(value => !value || typeof value.cardId !== 'string')
        || candidate.timelineEvents.some(value => !value || typeof value.date !== 'string' || typeof value.title !== 'string')) throw new Error('invalid draft')
    return { ...draft, storageKey, raw }
  }
  function collect() {
    if (!active()) return
    const { key, baseKey } = binding!
    const keys = new Set([baseKey, key]) // 兼容上一版单槽草稿
    for (let i = 0; i < localStorage.length; i++) {
      const item = localStorage.key(i)
      if (item?.startsWith(baseKey + '~')) keys.add(item)
    }
    const found: Candidate[] = []
    for (const item of keys) {
      try {
        const draft = readCandidate(item, baseKey)
        if (draft) {
          if (JSON.stringify(draft.form) !== binding!.baseline) found.push(draft)
          else void removeCandidate(draft).catch(() => {}) // 已提交的旧副本只在原页面不再编辑时清理
        }
      } catch { error.value = '部分本地草稿无法读取，未恢复损坏的内容。' }
    }
    candidates.value = found.sort((a, b) => b.updatedAt - a.updatedAt)
    pending.value = candidates.value[0] || null
  }
  function bind(projectId: string, cardId: string) {
    suspend()
    if (!user.token || !user.userId || !projectId) return
    const baseKey = `world-card-draft:v1:${[user.userId, projectId, cardId || 'new'].map(encodeURIComponent).join(':')}`
    const key = `${baseKey}~${writer}`
    binding = { key, baseKey, token: user.token, userId: user.userId, baseline: JSON.stringify(form.value) }
    baseSnapshot.value = binding.baseline
    // 活跃页面持有自己的槽锁，其他页面不能清理仍在编辑的副本；关闭页面自动释放。
    if (locks) {
      const lifetime = new Promise<void>(resolve => { releaseLease = resolve })
      void locks.request(key, () => lifetime).catch(() => { error.value = '无法保护多标签页草稿，请保留当前页面并保存条目。' })
    }
    try { collect() } catch { error.value = '本地草稿无法读取，请检查浏览器存储设置。' }
  }
  function flush(): boolean {
    if (!active()) return false
    if (pending.value) return true
    try {
      const snapshot = JSON.stringify(form.value)
      if (snapshot === binding!.baseline) {
        localStorage.removeItem(binding!.key); savedAt.value = 0; error.value = ''; return true
      }
      const draft: Draft = { version: 1, key: binding!.baseKey, updatedAt: Date.now(), baseline: baseSnapshot.value, form: form.value }
      localStorage.setItem(binding!.key, JSON.stringify(draft))
      savedAt.value = draft.updatedAt; error.value = ''; return true
    } catch {
      error.value = '本地草稿备份失败，请先保存条目，暂勿刷新或关闭页面。'
      return false
    }
  }
  async function removeCandidate(candidate: Candidate) {
    const context = binding
    const remove = () => {
      if (!active() || binding !== context || localStorage.getItem(candidate.storageKey) !== candidate.raw) return false
      localStorage.removeItem(candidate.storageKey); return true
    }
    if (candidate.storageKey === context?.key) return remove()
    // 没有 Web Locks 的浏览器不自动删除其他页面的副本。
    return locks ? locks.request(candidate.storageKey, { ifAvailable: true }, lock => lock ? remove() : false) : false
  }
  async function clear() {
    if (!active()) return
    const context = binding
    try {
      if (pending.value) {
        if (!await removeCandidate(pending.value)) { error.value = '这个草稿仍在其他标签页编辑或已经更新，请先关闭那个编辑页面，再重新打开此页。'; return }
        if (context === binding) collect()
      } else {
        localStorage.removeItem(binding!.key)
        if (restoredFrom) await removeCandidate(restoredFrom)
        if (context === binding) { restoredFrom = undefined; savedAt.value = 0 }
      }
    } catch { error.value = '无法清理本地草稿，请检查浏览器存储设置。' }
  }
  function restore() {
    if (!active() || !pending.value) return
    try {
      if (localStorage.getItem(pending.value.storageKey) !== pending.value.raw) {
        collect(); error.value = '其他标签页刚更新了草稿，请重新选择要恢复的版本。'; return
      }
      restoredFrom = pending.value
      baseSnapshot.value = pending.value.baseline // 保留旧基线，不能把旧内容伪装成基于最新版的修改。
      paused = true
      form.value = JSON.parse(JSON.stringify(pending.value.form))
      pending.value = null; paused = false; flush()
    } catch { paused = false; error.value = '草稿暂时无法恢复，填写的内容未被替换。' }
  }
  function rebase(baseline: string) { baseSnapshot.value = baseline; if (binding) binding.baseline = baseline; flush() }
  async function acceptSaved() {
    const context = binding
    await clear()
    if (binding && binding === context) { binding.baseline = JSON.stringify(form.value); baseSnapshot.value = binding.baseline }
  }
  watch(form, () => { if (!paused) flush() }, { deep: true, flush: 'sync' })
  return { pending, candidates, savedAt, error, baseSnapshot, serverChanged, bind, suspend, restore, clear, flush, rebase, acceptSaved }
}

// src/composables/世界观管理/useCardEditor.ts
import { ref, computed, unref, onScopeDispose, watch, type Ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { useCardDraft } from './useCardDraft'
import { useWorldStore } from '@/stores/world'
import type { CreateCardPayload, CardSummary } from '@/api/types/world'
import { cardToForm, mergeCardForms, type CardForm } from './useCardForm'

export function useCardEditor(
  form: Ref<CardForm>,
  resetForm: () => void,
  setFormData: (data: Partial<CardForm>) => void,
  checkQuota: () => Promise<boolean>,
  projectId: Ref<string> | string = ''
) {
  const route = useRoute()
  const store = useWorldStore()

  const draft = useCardDraft(form)
  watch(() => useUserStore().token, () => { loadVersion++; draft.suspend(); resetConflict(); resetForm(); loadError.value = true }, { flush: 'sync' })

  const saving = ref(false)
  const loading = ref(false)
  const loadError = ref(false)
  let loadVersion = 0
  const isCreating = ref(true)
  const conflicts = ref<(keyof CardForm)[]>([])
  const conflictChoices = ref<Partial<Record<keyof CardForm, 'local' | 'server'>>>({})
  const remoteForm = ref<CardForm | null>(null)
  let remoteVersion = ''
  let mergeResult: CardForm | null = null
  function resetConflict() { conflicts.value = []; conflictChoices.value = {}; remoteForm.value = null; mergeResult = null }

  const snapshot = () => JSON.stringify(form.value)
  const savedSnapshot = ref(snapshot())
  const markClean = () => { savedSnapshot.value = snapshot() }
  const isDirty = computed(() => !loading.value && !loadError.value && snapshot() !== savedSnapshot.value)

  // 仅显式传入的条目决定编辑目标，阅读页路由不能覆盖新建表单。
  const currentCardId = ref<string>('')

  // 优先使用传入的 projectId，如果没有则从路由获取
  const routeProjectId = computed(() => unref(projectId) || String(route.params.projectId || route.params.id || ''))
  const routeCardId = computed(() => currentCardId.value || undefined)

  const startCreating = () => {
    loadVersion++
    draft.suspend()
    resetConflict()
    resetForm()
    isCreating.value = true
    currentCardId.value = ''
    loading.value = false
    loadError.value = false
    markClean()
    draft.bind(routeProjectId.value, '')
  }

  // ===== 加载卡片数据 =====
  const loadCardData = async (cardData?: Pick<CardSummary, 'id'> | null) => {
    const version = ++loadVersion
    draft.suspend()
    resetConflict()
    const cardId = cardData?.id
    if (!cardId) {
      startCreating()
      return
    }

    // ✅ 记住当前卡片 ID
    currentCardId.value = cardId
    isCreating.value = false
    loadError.value = false

    const pid = routeProjectId.value
    if (!pid) {
      throw new Error('缺少 projectId')
    }

    loading.value = true
    try {
      // 表单使用独立副本，未保存的图库、引用和时间线不能改动阅读缓存。
      const fullCard = JSON.parse(JSON.stringify(await store.fetchCardDetail(pid, cardId)))
      if (version !== loadVersion) return

      if (!fullCard) {
        throw new Error('卡片数据为空')
      }

      setFormData(cardToForm(fullCard))
      markClean()
      draft.bind(pid, cardId)

    } catch (error) {
      if (version !== loadVersion) return
      console.error('加载卡片数据失败:', error)
      loadError.value = true
    } finally {
      if (version === loadVersion) loading.value = false
    }
  }

  function resolveConflicts() {
    if (!remoteForm.value || !mergeResult || conflicts.value.some(key => !conflictChoices.value[key])) return
    for (const key of conflicts.value) {
      if (conflictChoices.value[key] === 'server') Object.assign(mergeResult, { [key]: remoteForm.value[key] })
    }
    const baseline = JSON.stringify(remoteForm.value)
    form.value = JSON.parse(JSON.stringify(mergeResult))
    savedSnapshot.value = baseline
    draft.rebase(baseline)
    resetConflict()
  }
  async function prepareUpdate(version: number) {
    const latest = await store.fetchCardDetail(routeProjectId.value, currentCardId.value, true)
    if (version !== loadVersion) return false
    const remote = cardToForm(latest)
    let base: CardForm | null = null
    try { base = JSON.parse(draft.baseSnapshot.value || savedSnapshot.value) } catch { /* 旧草稿无有效基线时必须人工核对 */ }
    const result = mergeCardForms(base, form.value, remote)
    remoteVersion = latest.updatedAt
    if (result.conflicts.length) {
      remoteForm.value = remote; mergeResult = result.merged
      conflicts.value = result.conflicts; conflictChoices.value = {}
      return false
    }
    form.value = result.merged
    savedSnapshot.value = JSON.stringify(remote)
    draft.rebase(savedSnapshot.value)
    return true
  }

  // ===== 保存卡片 =====
  const handleSave = async (onSaved: (cardId: string) => void) => {
    if (saving.value || loading.value || loadError.value || draft.pending.value || conflicts.value.length) return
    if (!form.value.title.trim()) {
      ElMessage.warning('请输入标题')
      return
    }

    saving.value = true
    const version = loadVersion
    const pid = routeProjectId.value
    try {
      if (isCreating.value) {
        const canCreate = await checkQuota()
        if (version !== loadVersion) return
        if (!canCreate) {
          ElMessage.warning('当前世界卡片数量已达上限，请扩容')
          return
        }
      }

      if (!isCreating.value && !await prepareUpdate(version)) return

      const cardPayload: CreateCardPayload = {
        title: form.value.title.trim(),
        type: form.value.type,
        coverImage: form.value.coverImage,
        galleryImages: form.value.galleryImages,
        attributes: form.value.attributes.map(attribute => ({ ...attribute, value: String(attribute.value ?? '') })),
        description: form.value.description.trim(),
        content: JSON.stringify(form.value.content || {}),   // ✅ 对象 → 字符串
        tags: form.value.tags,
        contentBlocks: form.value.contentBlocks,
        timelineEvents: form.value.timelineEvents,
        relations: form.value.relations,
      }

      if (isCreating.value) {
        const created = await store.createCard(pid, cardPayload)
        if (version !== loadVersion) return
        currentCardId.value = created.id
        isCreating.value = false
        ElMessage.success('已创建')
      } else {
        if (!currentCardId.value) throw new Error('缺少卡片 ID')
        await store.updateCard(currentCardId.value, { ...cardPayload, expectedUpdatedAt: remoteVersion })
        ElMessage.success('已更新')
      }

      if (version === loadVersion) { await draft.acceptSaved(); if (version !== loadVersion) return; markClean(); onSaved(currentCardId.value) }
    } catch (error: any) {
      console.error('保存失败:', error)
      if (version !== loadVersion) return
      if (error?.response?.status === 409 && error?.response?.data?.code === 'WORLD_CARD_CONFLICT') {
        ElMessage.warning('条目刚被其他页面更新，本地草稿已保留。再次保存时会核对最新内容。')
      } else if (error?.response?.data?.code === 'CARD_LIMIT_EXCEEDED') {
        ElMessage.warning({
          message: error.response.data.message || '卡片数量已达上限，请扩容',
          duration: 5000,
          showClose: true,
        })
      } else {
        ElMessage.error(error?.response?.data?.message || '保存失败，填写的内容已保留，请重试')
      }
    } finally {
      saving.value = false
    }
  }

  // ===== 删除卡片 =====
  const handleDelete = async (onDeleted: () => void) => {
    try {
      await ElMessageBox.confirm('确定删除吗？', '提示', { type: 'warning' })
      const cardId = currentCardId.value
      if (!cardId) {
        throw new Error('缺少卡片 ID')
      }
      await store.deleteCard(cardId)
      await draft.acceptSaved()
      markClean()
      ElMessage.success('已删除')
      onDeleted()
    } catch (error) {
      if (error !== 'cancel') console.error(error)
    }
  }

  onScopeDispose(() => { loadVersion++ })
  return {
    draft,
    conflicts, conflictChoices, remoteForm, resolveConflicts,
    isDirty,
    markClean,
    saving,
    loading,
    loadError,
    isCreating,
    routeProjectId,
    routeCardId,
    currentCardId,
    startCreating,
    loadCardData,
    handleSave,
    handleDelete,
  }
}

import { onMounted, onBeforeUnmount, ref, watch, type Ref } from 'vue'
import ForceGraph3D, { type ForceGraph3DInstance, type LinkObject } from '3d-force-graph'
import type { WorldGraphNode, WorldGraphEdge } from '@/utils/worldGraph'
import { getNodeCameraPosition } from '@/utils/worldGraph'
import { createNodeObject } from '@/utils/worldGraphSprite'

type GraphLink = Omit<WorldGraphEdge, 'source' | 'target'> & LinkObject<WorldGraphNode>
interface GraphControls { autoRotate: boolean; autoRotateSpeed: number; enableDamping: boolean; dampingFactor: number }

/** 组件只提供图数据和选中回调，3D 实例、尺寸监听与释放在此处管理。 */
export function useWorldGraph(container: Ref<HTMLElement | null>,
  data: Ref<{ nodes: WorldGraphNode[]; links: WorldGraphEdge[] }>, onSelect: (id: string) => void) {
  const loading = ref(false)
  const autoRotate = ref(true)
  let graph: ForceGraph3DInstance<WorldGraphNode, GraphLink> | null = null

  function refresh() {
    // 图库会修改坐标与边的端点，传入副本避免污染 Store 派生数据。
    graph?.graphData({ nodes: data.value.nodes.map(node => ({ ...node })), links: data.value.links.map(link => ({ ...link })) })
  }
  function resize() {
    if (graph && container.value) graph.width(container.value.clientWidth).height(container.value.clientHeight)
  }
  function toggleRotate() {
    autoRotate.value = !autoRotate.value
    if (graph) (graph.controls() as GraphControls).autoRotate = autoRotate.value
  }
  const resetCamera = () => graph?.cameraPosition({ x: 0, y: 0, z: 400 }, { x: 0, y: 0, z: 0 }, 1000)

  onMounted(() => {
    if (!container.value) return
    loading.value = true
    try {
      graph = new ForceGraph3D(container.value) as unknown as ForceGraph3DInstance<WorldGraphNode, GraphLink>
      graph.width(container.value.clientWidth).height(container.value.clientHeight)
        .backgroundColor('#fafafa').graphData({ nodes: [], links: [] })
        .nodeThreeObject(createNodeObject).nodeThreeObjectExtend(false)
        .linkColor(link => link.color).linkWidth(link => link.width).linkOpacity(0.6)
        .linkDirectionalArrowLength(link => link.isEmbed ? 0 : 3.5)
        .linkDirectionalArrowRelPos(1).linkDirectionalArrowColor(link => link.color)
        .linkLabel(link => link.label || '')
        .onNodeClick(node => {
          onSelect(node.id)
          const { position, target } = getNodeCameraPosition(node)
          graph?.cameraPosition(position, target, 1000)
        })
        .onBackgroundClick(() => onSelect(''))
        .d3AlphaDecay(0.02).d3VelocityDecay(0.3).warmupTicks(80).cooldownTicks(120)
      Object.assign(graph.controls(), { autoRotate: autoRotate.value, autoRotateSpeed: 0.5, enableDamping: true, dampingFactor: 0.1 })
      refresh()
      window.addEventListener('resize', resize)
    } finally { loading.value = false }
  })
  watch(data, refresh, { deep: true })
  onBeforeUnmount(() => {
    window.removeEventListener('resize', resize)
    try { graph?._destructor() }
    catch (error) { console.warn('释放世界观图谱失败:', error) }
    finally { graph = null }
  })
  return { loading, autoRotate, refresh, toggleRotate, resetCamera }
}

// src/composables/世界观管理/useCardTypeOptions.ts
import { computed } from 'vue'
import { useWorldStore } from '@/stores/world'
import { CardTypeMeta } from '@/views/世界观管理/card_type'

export function useCardTypeOptions() {
  const store = useWorldStore()

  const cardTypeOptions = computed(() => {
    if (store.cardTypes && store.cardTypes.length) {
      return store.cardTypes
    }
    return Object.entries(CardTypeMeta).map(([value, meta]) => ({
      value,
      label: meta.label,
    }))
  })

  return { cardTypeOptions }
}

